import { FeatureStoreSnapshot } from '@ulta-plus/extension-feature-toggle';
import { useMemo } from 'react';

import { LocalStorageKey } from '@app/storage/local/types/sharedTypes';
import { useBridgeStore } from '@bridgeStore/index';
import { useShallow } from 'zustand/react/shallow';

export const useContentFeaturesList = () => {
  const [store] = useBridgeStore(
    useShallow((s) => [s[LocalStorageKey.FeatureStoreV2]]),
  );

  const featureStore: Partial<FeatureStoreSnapshot> = useMemo(() => {
    if (!store) return {};
    return {
      ...store,
      featuresList: {
        ...store.featuresList,
        ...store.featuresListLocal,
      },
    };
  }, [store]);

  return featureStore;
};
